// Using a simple hash map or a sorted array would be better if timestamps are very spread out.
// Given it's a log file, let's see if we can use a hash table or just collect and sort.
// Actually, since we need to sort at the end anyway, let's just use a hash table to aggregate.

typedef struct Node {
    long bucket_ts;
    float max_cpu;
    float max_mem;
    float max_disk;
    struct Node *next;
} Node;

