    new_node->bucket_ts = bucket_ts;
    new_node->max_cpu = (code == 1) ? val : 0.0f;
    new_node->max_mem = (code == 2) ? val : 0.0f;
    new_node->max_disk = (code == 3) ? val : 0.0f;
    new_node->next = table[h];
    table[h] = new_node;
}

